content:
:root{--paper:#f4f1e8;--paper-2:#d9d5c9;--ink:#090909;--red:#aa342e;--blue:#5e70dc;--green:#24a63f;--yellow:#ffd94a;--muted:#aaa79f;--font:"Pixelify Sans",system-ui,sans-serif}
*{box-sizing:border-box}
html{color-scheme:light}
body{margin:0;min-height:100vh;background:#25262b;color:var(--paper);font-family:var(--font);font-size:18px}
button,select,textarea{font:inherit;color:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed}#scene{display:none}
.material-symbols-outlined{font-family:"Material Symbols Outlined";font-size:38px;line-height:1;font-variation-settings:"FILL" 0,"wght" 500,"GRAD" 0,"opsz" 24}
.desktop-shell{width:min(1760px,100%);min-height:100vh;margin:0 auto;background:var(--paper);border-inline:5px solid var(--ink);box-shadow:0 0 0 2px var(--paper),0 0 0 7px var(--ink)}
.topbar{height:64px;padding:0 20px;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:28px;border-bottom:5px double var(--ink);background:var(--paper);color:var(--ink)}
.brand{color:var(--red);font-size:2rem;font-weight:700;text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:5px;white-space:nowrap}.game-menu{display:flex;gap:22px;font-size:1.65rem;font-weight:700}.game-menu span{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:5px}.top-actions{display:flex;align-items:center;gap:8px}
.menu-action,.career-stars{min-height:38px;padding:6px 10px;border:3px double var(--ink);background:var(--paper);color:var(--ink);font-size:.86rem;font-weight:700}.menu-action:hover,.menu-action:focus-visible{background:var(--ink);color:var(--paper)}
.file-label{position:relative;cursor:pointer}.file-label input{display:block;position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.game-console{padding:10px;background:var(--paper)}.screen-grid{display:grid;grid-template-columns:minmax(360px,.88fr) minmax(520px,1.12fr);gap:8px;min-height:calc(100vh - 84px)}.city-column,.intel-column{min-width:0;display:grid;gap:8px}.city-column{grid-template-rows:auto minmax(0,1fr)}.intel-column{grid-template-rows:auto minmax(0,1fr) 116px}
.retro-window{background:var(--ink);color:var(--paper);border:7px double var(--paper);outline:3px solid var(--ink);box-shadow:0 0 0 5px var(--paper),0 0 0 8px var(--ink)}
.location-header{min-height:104px;padding:10px 22px;text-align:center}.location-header h2{margin:0;font-size:2.2rem;line-height:1}.time-line{margin-top:4px;font-size:1.35rem}.time-line span{color:var(--yellow);font-weight:700}.time-track{height:7px;margin:8px auto 0;max-width:330px;background:#3b3b3b;border:1px solid var(--paper)}.time-track span{display:block;height:100%;background:var(--green);transition:width .25s}.danger .time-track span{background:var(--red)}
.city-frame{position:relative;margin:0;min-height:470px;overflow:hidden;background:#1a1a1a}.city-frame img{display:block;width:100%;height:100%;object-fit:cover;image-rendering:pixelated}.city-frame figcaption{position:absolute;inset:auto 0 0;display:flex;justify-content:space-between;padding:8px 12px;background:var(--ink);border-top:4px double var(--paper);font-size:.8rem;text-transform:uppercase}
.mission-header{min-height:104px;padding:10px 18px;display:grid;grid-template-columns:auto 1fr;align-items:center;gap:16px}.mission-header>div{display:flex;align-items:center;gap:8px;color:var(--yellow);font-size:.75rem;text-transform:uppercase}.status-light{width:12px;height:12px;border:2px solid var(--paper);background:var(--green)}.mission-header h1{margin:0;font-size:1.75rem;line-height:1.05;text-transform:uppercase}
.intel-frame{padding:20px 24px;overflow:auto}.briefing{margin:0 0 16px;padding-bottom:14px;border-bottom:3px double var(--paper);font-size:1.05rem;line-height:1.25}.city-intel{display:grid;grid-template-columns:minmax(180px,.65fr) 1.35fr;gap:18px}.case-context{margin:0;color:var(--muted);font-size:.94rem;line-height:1.3}.city-briefing{border-left:4px solid var(--green);padding-left:16px}.city-briefing>span{color:var(--green);font-size:.72rem;letter-spacing:.08em}.city-briefing h3{margin:3px 0 7px;font-size:1.45rem}.city-briefing p{margin:0;line-height:1.3}.city-briefing ul{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 18px;margin:10px 0 0;padding-left:18px;color:var(--muted);font-size:.83rem;line-height:1.2}
.places-title{display:flex;justify-content:space-between;align-items:end;margin-top:18px;padding-top:10px;border-top:3px double var(--paper);color:var(--green);font-size:.8rem;letter-spacing:.05em}.places-title small{color:var(--muted)}.location-actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:8px}.investigate{min-height:76px;padding:8px;border:4px double var(--paper);background:var(--ink);display:grid;grid-template-columns:32px 1fr;text-align:left;align-content:center}.investigate:hover,.investigate:focus-visible{background:var(--paper);color:var(--ink);outline:4px solid var(--green);outline-offset:-4px}.investigate .material-symbols-outlined{grid-row:1/3;font-size:26px;color:var(--green)}.investigate strong{font-size:.92rem;line-height:1}.investigate small{margin-top:4px;color:var(--muted);font-size:.7rem}.investigate.done{opacity:.55}
.command-bar{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.command-button{border:7px double var(--ink);background:var(--paper);color:var(--ink);display:grid;place-items:center;align-content:center;gap:3px;font-size:.92rem;font-weight:700;box-shadow:inset 0 0 0 2px var(--paper)}.command-button:hover,.command-button:focus-visible{outline:6px solid var(--green);outline-offset:-9px}.command-button.crime .material-symbols-outlined{color:#243bc2}.command-button.issued{background:var(--green)}
.eyebrow{margin:0 0 8px;color:var(--green);font-size:.8rem;letter-spacing:.08em;text-transform:uppercase}.modal{width:min(980px,calc(100% - 32px));max-height:calc(100vh - 32px);padding:22px;border:7px double var(--paper);outline:4px solid var(--ink);background:var(--ink);color:var(--paper);box-shadow:0 0 0 5px var(--paper),0 0 0 9px var(--ink)}.modal::backdrop{background:rgba(0,0,0,.78)}.modal-close{position:absolute;right:10px;top:7px;width:38px;height:38px;border:3px double var(--paper);background:var(--ink);color:var(--paper);font-size:1.5rem;line-height:1}.modal h2{margin:0 44px 10px 0;font-size:1.7rem}.modal p,.modal #message-copy{line-height:1.35}.compact-modal{width:min(560px,calc(100% - 32px))}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.primary,.secondary{padding:11px 16px;border:4px double var(--paper);font-weight:700}.primary{background:var(--green);color:var(--ink)}.secondary{background:var(--ink);color:var(--paper)}.wide{width:100%;margin-top:10px}
.map-modal{width:min(1180px,calc(100% - 32px))}.map-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.map-heading h2{margin:0}.map-legend{display:flex;gap:14px;font-size:.7rem}.map-legend span{display:flex;align-items:center;gap:5px}.node{width:10px;height:10px;display:inline-block;border:2px solid var(--paper)}.node.current{background:var(--yellow)}.node.available{background:var(--blue)}.node.visited{background:#777}
.map-layout{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:12px}.map-card{position:relative;min-height:520px;overflow:hidden;background:var(--blue);border:5px double var(--paper)}.map-grid{position:absolute;inset:0;background:var(--blue) url("assets/ui/brasil-map.webp") center/cover no-repeat;image-rendering:pixelated}#route-lines{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.city{position:absolute;transform:translate(-50%,-50%);min-width:54px;min-height:54px;padding:0;border:0;background:none;color:var(--paper);text-align:left}.city-pulse{position:absolute;left:18px;top:18px;width:15px;height:15px;border:3px solid var(--ink);background:var(--blue);box-shadow:0 0 0 2px var(--paper)}.city.current .city-pulse{background:var(--yellow)}.city.visited .city-pulse{background:#777}.city-name,.city small{position:absolute;left:42px;transform:none;white-space:nowrap;color:var(--ink);text-align:left;text-shadow:1px 1px var(--paper),-1px -1px var(--paper)}.city-name{top:7px;font-size:1rem;font-weight:700}.city small{top:29px;font-size:.7rem}.city[data-city="sao_paulo"] .city-name,.city[data-city="sao_paulo"] small{left:auto;right:36px;text-align:right}.city[data-city="recife"] .city-name,.city[data-city="recife"] small{left:auto;right:50px;text-align:right}.city[data-city="recife"] .city-name{top:-18px}.city[data-city="recife"] small{top:3px}.city[data-city="porto_alegre"] .city-name,.city[data-city="porto_alegre"] small{left:25.5px;right:auto;transform:translateX(-50%);text-align:center}.city[data-city="porto_alegre"] .city-name{top:-42px}.city[data-city="porto_alegre"] small{top:-21px}
.route-panel{padding:14px;border:5px double var(--paper)}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.section-head h2{margin:0}.route-log{display:grid;margin-top:12px}.route-item{display:grid;grid-template-columns:28px 10px 1fr;align-items:center;gap:6px;min-height:35px}.route-item span{color:var(--muted);font-size:.75rem}.route-item i{width:7px;height:7px;background:var(--green)}
.evidence-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.evidence,.empty-state{padding:14px;border:4px double var(--paper)}.evidence>div{display:flex;justify-content:space-between;color:var(--green);font-size:.75rem}.evidence em{font-style:normal}.evidence h3{margin:8px 0 4px}.evidence p,.empty-state p{margin:0;color:var(--muted);font-size:.86rem}.empty-state span{color:var(--green);font-size:.75rem}.empty-state strong{display:block;margin:8px 0}.panel-help{color:var(--muted)}
.dossier-form{display:grid;gap:10px}.dossier-form label span{display:block;margin-bottom:5px;color:var(--muted)}select{width:100%;padding:10px;border:4px double var(--paper);background:var(--ink)}.dossier-status{display:flex;justify-content:space-between;padding:10px 0;border-top:2px solid var(--paper)}#notebook{width:100%;min-height:240px;padding:12px;border:4px double var(--paper);background:#111;color:var(--paper);resize:vertical}.note-footer{display:flex;justify-content:space-between;margin-top:7px;color:var(--muted);font-size:.72rem}
button:focus-visible,select:focus-visible,textarea:focus-visible,input:focus-visible,.file-label:focus-within{outline:4px solid var(--green);outline-offset:2px}
@media(max-width:980px){.topbar{grid-template-columns:1fr auto}.game-menu{display:none}.screen-grid{grid-template-columns:1fr}.city-frame{min-height:420px}.intel-column{grid-template-rows:auto auto 105px}.map-layout{grid-template-columns:1fr}.route-panel{display:none}}
@media(max-width:620px){body{font-size:16px}.desktop-shell{border:0;box-shadow:none}.topbar{height:auto;min-height:58px;padding:8px 10px;gap:8px}.brand{font-size:1.35rem}.top-actions{gap:4px}.menu-action{padding:5px 7px;font-size:.68rem}.career-stars{display:none!important}.game-console{padding:6px}.screen-grid{min-height:0}.location-header,.mission-header{min-height:84px}.location-header h2{font-size:1.7rem}.city-frame{min-height:300px}.mission-header{grid-template-columns:1fr}.mission-header h1{font-size:1.45rem}.intel-frame{padding:16px}.briefing{font-size:.95rem}.city-intel{grid-template-columns:1fr}.city-briefing ul{grid-template-columns:1fr}.location-actions{grid-template-columns:1fr}.investigate{min-height:64px}.intel-column{grid-template-rows:auto auto auto}.command-bar{position:static;height:88px;grid-template-columns:repeat(4,1fr);background:var(--paper);padding-top:5px}.command-button{border-width:5px;font-size:.68rem}.material-symbols-outlined{font-size:28px}.map-card{min-height:420px}.map-heading{display:block}.map-legend{margin-top:8px}.evidence-list{grid-template-columns:1fr}.modal{padding:17px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
